$('#import').onclick=()=>{try{const imported=parseImport($('#import-text').value),s=imported.snapshot||imported,errors=validateSnapshot(s);if(errors.length)throw new Error(errors.join('; '));if(imported.assumptions)valueCompany(s,imported.assumptions);let c=companies.find(c=>c.ticker===s.ticker);if(!c){c={ticker:s.ticker,name:s.name||s.ticker,snapshots:[]};companies.push(c)}c.snapshots.unshift(s);selected=s;if(imported.assumptions){a={...defaults,...imported.assumptions};setupFields();$('#thesis').value=imported.thesis||''}renderPicker();chooseCompany(s.ticker);if(imported.assumptions){a={...defaults,...imported.assumptions};setupFields();render()}renderLedger();appText($('#import-result'),'Valid snapshot loaded. Open Valuation workbench to use it.');toast('Snapshot imported locally.')}catch(e){appText($('#import-result'),e.message)}};
