$('#reveal-actuals').onclick=async()=>{try{if(!locked)throw new Error('Lock an experiment before revealing later filings');if(locked.snapshot.raw?.id==='MSFT-FY2019'){$('#original-scorecard').click();$('#actual-results').innerHTML='The sourced Microsoft FY2020–FY2021 comparison appears in the original scorecard below. No later annual-reference snapshot is used as a matched next-year outcome.';return}const c=companies.find(c=>c.ticker===locked.snapshot.ticker);let outcome=[];if(locked.snapshot.ticker==='NVDA'){try{const o=await(await fetch('./data/nvda-fy2025-outcome.json')).json();outcome=[{periodEnd:o.periodEnd,revenue:o.facts.revenue,ebit:o.facts.EBIT,sourceUrl:o.sourceURL}]}catch{}}const later=[...(c?.snapshots||[]),...outcome].filter(s=>s.periodEnd>locked.snapshot.periodEnd).sort((x,y)=>x.periodEnd.localeCompare(y.periodEnd));if(!later.length)throw new Error('No subsequent sourced operating snapshot loaded for this case');const forecast=valueCompany(locked.snapshot,locked.assumptions).rows;$('#actual-results').innerHTML=table(['Fiscal period','Forecast revenue','Actual revenue','Revenue error','Forecast margin','Actual margin','Forecast FCFF'],later.map(s=>{const offset=Math.round((Date.parse(s.periodEnd)-Date.parse(locked.snapshot.periodEnd))/(365.25*864e5));const r=forecast[offset-1];return [`<a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">${esc(s.periodEnd)} ↗</a>`,r?n(r.revenue,0):'—',n(s.revenue,0),r?pct((r.revenue-s.revenue)/s.revenue):'—',r?pct(r.margin):'—',pct(s.ebit/s.revenue),r?n(r.fcff,0):'—']}))+`<p class="micro">${appMark("Revenue error = (forecast − actual) / actual. Fiscal periods matched by nearest annual interval. Reported CFO − capex is not unlevered FCFF: actual FCFF error remains unavailable until interest, taxes, working capital and accounting adjustments are reconciled. Later source filings are available in the ledger.")}</p>`}catch(e){appText($('#actual-results'),e.message)}};
$('#revise').onclick=()=>{try{if(!locked)throw new Error('Lock an experiment first');if(selected?.ticker!==locked.snapshot.ticker)throw new Error('Select the locked company before revising its case');if(!$('#diagnosis').value.trim())throw new Error('Add evidence and a next test before saving a revision');const revised=lockExperiment(locked.snapshot,a,locked.asOf);revised.parentId=locked.id;if(locked.provenance)revised.provenance=locked.provenance;revised.version=(locked.version||1)+1;revised.hindsightInformed=true;revised.thesis=$('#thesis').value;revised.diagnosis={type:$('#diagnosis-type').value,note:$('#diagnosis').value};revised.forecast=valueCompany(locked.snapshot,a).rows;saved.push(revised);locked=revised;persist();toast('New version saved. Original assumptions preserved.')}catch(e){toast(e.message)}};

