$('#load-case').onclick=()=>{clearCaseDiagnostics();pathEditNotice='';const c=researchCases.find(c=>c.snapshotId===selected?.raw?.id);if(!c){toast('No dated case available for this snapshot. Write your own sourced assumptions.');return}activeCase=c;if(c.snapshotOverrides||c.snapshotOverride){const original=companies.find(company=>company.ticker===selected.ticker)?.snapshots.find(s=>s.raw?.id===c.snapshotId)||selected;const overrides=Object.fromEntries(Object.entries(c.snapshotOverrides||c.snapshotOverride).filter(([k])=>['shares','debt','ebit','cash','revenue'].includes(k)));selected={...original,...overrides,shareBasis:c.adjustedShareBasis||c.snapshotOverride?.shareBasis||original.shareBasis,coverShareDate:c.snapshotOverride?.coverShareDate||original.coverShareDate,caseAdjustmentNotes:c.snapshotAdjustmentNotes||'Case-specific model adjustments; inspect the source-to-model bridge.'}}a={...defaults,...c.assumptions};$('#thesis').value=c.thesis;$('#case-notice').classList.remove('hidden');$('#case-notice').innerHTML=`<b>${esc(c.classification)}</b><br>${esc(c.thesis)}<br>${esc((c.uncertainty||[]).join(' '))}<br>${(c.sourceUrls||[]).map((u,i)=>`<a href="${esc(u)}" target="_blank" rel="noopener">${appMark("Evidence {number} \u2197",{number:i+1})}</a>`).join(' · ')}`;setupFields();render();$('#case-notice').classList.remove('hidden');$('#case-analysis').classList.remove('hidden');$('#case-analysis-content').innerHTML=(c.snapshotId==='NVDA-FY2021'?`<div class="notice"><b>${appMark("Versioned arithmetic correction:")}</b>${appMark(" the source ledger’s platform-growth bridge sums to 32.0186%, not 32.5%. The original frozen 32.5% forecast and $247.06 value are preserved. A separately computed arithmetic-consistent diagnostic yields $246.22; it is a post-freeze correction, not improved historical foresight.")}<br><b>${appMark("Separate mechanism stresses:")}</b>${appMark(" a genuine contracting-cycle bear case is $92.29 versus the original $102.75 bear. Fading sales-to-capital to 0.6751 by year ten (consistent with 16% mature ROIC at a 30% margin and 21% tax) gives $243.62 versus $247.06. The original path implies a 71.1% incremental return before an abrupt 16% terminal regime; the original freeze stays unchanged.")}<br><b>${appMark("Unresolved awards:")}</b>${appMark(" a 0–5% equity haircut is only a sensitivity, not a valuation of outstanding options or RSUs.")}</div>`:'')+table(['Dated evidence','Source location','Forecast interpretation'],(c.sourceAssumptionLedger||[]).map(r=>[esc(r.fact),esc(r.source),esc(r.inference)]))+`<h3>${appMark("Accounting treatment & unresolved claims")}</h3>`+Object.entries(c.accounting||{}).map(([k,v])=>'<p><b>'+esc(k)+':</b> '+esc(v)+'</p>').join('')+`<h3>${appMark("Missing mechanisms / diagnostics")}</h3><p>`+esc((c.diagnosticFlags||[]).join(' '))+'</p><p class="micro">Freeze: '+esc(c.freezeTimestampUTC)+' · SHA256 '+esc(c.originalFreezeSHA256)+'</p>';toast('Dated assumptions loaded; review the evidence and limitations before locking.')};
$('#sparse-prices').onclick=async()=>{try{if(!locked||locked.snapshot.ticker!=='NVDA')throw new Error('Lock an NVIDIA case first');const d=await(await fetch('./data/nvda-price-observations.json')).json();const start=d.observations.find(o=>o.date>locked.asOf.slice(0,10)||(o.date===locked.asOf.slice(0,10)&&locked.asOf.slice(11,16)<='14:30')),end=d.observations.find(o=>o.date===d.endpointDate);if(!start||!end||start.date===end.date)throw new Error('No later price pair for this cutoff');const divisor=locked.snapshot.raw?.fiscalYear===2021?40:10;$('#history-results').innerHTML=`<b>${appMark("Sparse historical observations, not a strategy backtest")}</b>${table(['Observation','Split-adjusted price','Evidence'],[start,end].map(o=>[esc(o.date),n(o.splitAdjustedPrice,3),`<a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener">${esc(o.sourceTitle)} ↗</a>`]))}<p>${appMark("Price-only return: {return}. Locked intrinsic value on the same post-June-2024 split basis: {value} USD/share.",{return:pct(end.splitAdjustedPrice/start.splitAdjustedPrice-1),value:n(locked.intrinsicValue/divisor,2)})}</p><p class="micro">${appMark("Entry observation is the first sourced date on or after the cutoff ({date}), not necessarily that day's open or official close. ",{date:start.date})}${esc(start.reportedPriceType)}. ${esc(d.dividends)}${appMark(" Four ex-post selected dates, unequal holding periods, one common endpoint. Future splits are used only for outcome unit reconciliation. No daily series or licensed market feed.")}</p>`}catch(e){appText($('#history-results'),e.message)}};



