$('#reverse-dcf').onclick=async()=>{try{if(!locked)throw new Error('Lock a case before revealing reverse-DCF diagnostics');const d=await(await fetch('./data/reverse-dcf-diagnostics.json')).json();const c=d.cases.find(c=>c.snapshotId===locked.snapshot.raw?.id);if(!c)throw new Error('No independently tested reverse diagnostic for this snapshot');$('#reverse-results').innerHTML=table(['Original frozen base','Original bull','Dated quote','Bull / quote gap'],[[n(c.baseValue,2),n(c.bullValue,2),n(c.quoteOriginalBasis,2),n(c.bullToQuoteGapPct,1)+'%']])+`<p class="micro">${appMark("These diagnostics refer to the original researched freeze, not your edited local case. ")}<a href="${esc(c.quoteSource)}" target="_blank" rel="noopener">${appMark("Quote evidence ↗")}</a> · ${esc(c.quoteDate)}. ${esc(c.timing)} ${esc(c.quoteCharacterization)}</p><p><b>${appMark("Conditional operating path:")}</b>${appMark(" add {shift} percentage points to each of the first five growth rates, taper to zero by year ten, retaining all other assumptions. Implied year-one growth {growth}; year-five revenue {revenue}m.",{shift:n(c.growthPremiumDiagnostic.parameter*100,2),growth:pct(c.growthPremiumDiagnostic.year1Growth),revenue:n(c.growthPremiumDiagnostic.year5Revenue,0)})}</p><p><b>${appMark("Alternative conditional discount rate:")}</b>${appMark(" shift all annual and terminal WACC rates by {shift} percentage points; implied terminal WACC {wacc}. This is not an observed historical rate.",{shift:n(c.waccShiftDiagnostic.parameter*100,2),wacc:pct(c.waccShiftDiagnostic.impliedTerminalWacc)})}</p><p class="micro">${esc(c.interpretation)}${appMark(" These are value-to-price gaps, not errors against a known true intrinsic value. Nothing is applied to the original forecast.")}</p>`}catch(e){appText($('#reverse-results'),e.message)}};

$('#original-scorecard').onclick=async()=>{try{if(!locked)throw new Error('Lock a case before revealing its original scorecard');if(locked.snapshot.raw?.id==='MSFT-FY2019'){const d=await(await fetch('./data/msft-business-outcome-evaluation.json')).json();$('#original-scorecard-results').innerHTML=`<h3>${appMark("Microsoft: original frozen business forecast")}</h3>`+table(['Outcome year','Base revenue forecast','Actual revenue','Revenue error','EBIT error','Margin error (pp)'],d.evaluations.map(e=>{const c=e.comparison.base;return [`<a href="${esc(e.sourceURL)}" target="_blank" rel="noopener">FY${e.fiscalYear} ↗</a>`,n(c.forecastRevenue,0),n(c.actualRevenue,0),n(c.revenueErrorPct,2)+'%',n(c.ebitErrorPct,2)+'%',n(c.marginErrorPercentagePoints,2)]}))+`<p>${esc(d.interpretation)}</p><p class="micro">${appMark("Errors = (forecast − actual) / actual. Original frozen assumptions only; your local edits are not scored here. No actual unlevered FCFF, market-price or return evaluation is claimed. ")}<a href="./data/msft-business-outcome-evaluation.json" target="_blank">${appMark("Full three-state outcome evaluation")}</a> · <a href="./data/msft-independent-check.json" target="_blank">${appMark("Independent arithmetic checks and sensitivities")}</a> · <a href="./data/msft-annual-scenario-paths.csv" download>${appMark("Annual scenario paths CSV")}</a></p>`;return}const d=await(await fetch('./data/frozen-case-evaluation.json')).json();const c=d.cases.find(c=>c.snapshotId===locked.snapshot.raw?.id);if(!c)throw new Error('No original scorecard for this snapshot');$('#original-scorecard-results').innerHTML=`<h3>${appMark("Operating forecasts: original frozen research case")}</h3>`+table(['Outcome fiscal year','Forecast revenue','Actual revenue','Revenue error','Margin error (pp)','EBIT error'],c.businessForecastComparisons.map(r=>[`<a href="${esc(r.actualSource)}" target="_blank" rel="noopener">FY${r.actualFiscalYear} ↗</a>`,n(r.forecastRevenue,0),n(r.actualRevenue,0),n(r.revenueErrorPct,1)+'%',n(r.operatingMarginErrorPercentagePoints,1),n(r.ebitErrorPct,1)+'%']))+`<p class="micro">${esc(c.businessOutcomeStatus)}${appMark(". Revenue/EBIT error = (forecast − actual) / actual. Actual unlevered FCFF remains unconstructed. These numbers refer to the original frozen case, not your edited assumptions.")}</p><h3>${appMark("Market comparison: a different question")}</h3><p>${appMark("Base value-to-price gap: {gap}%. Subsequent price-only return to {date}: {return}%.",{gap:n(c.baseValueToPriceGapPct,1),date:c.returnEndDate,return:n(c.subsequentPriceOnlyReturnPct,1)})}</p><p class="micro">${esc(c.gapMeaning)}${appMark(". Entry-day quote was observed after the research cutoff. ")}${esc(c.entryPriceCharacterization)}. ${esc(d.priceReturnLimits)} ${esc(d.caseSelectionLimits)}</p>`}catch(e){appText($('#original-scorecard-results'),e.message)}};

$('#research-addenda').onclick=async()=>{try{if(!activeCase)throw new Error('Load a dated research case first');if(activeCase.snapshotId==='MSFT-FY2019'){ $('#research-addenda-results').innerHTML=`<p>${appMark("Microsoft accounting, rate assumptions and terminal capital fade are documented in the dated case above and its ")}<a href="./data/research-versions/MSFT-FY2019-frozen-v1.json" target="_blank">${appMark("original versioned freeze")}</a>${appMark(". It has no NVIDIA quarterly-guidance addendum.")}</p>`;return}const d=await(await fetch('./data/research-addenda.json')).json(),c=d.cases.find(c=>c.snapshotId===activeCase.snapshotId),b=d.quarterlyBridge.find(c=>c.snapshotId===activeCase.snapshotId);if(!c)throw new Error('No supplemental checks available');const rf=c.rateEvidence.riskFree,erp=c.rateEvidence.equityRiskPremium;$('#research-addenda-results').innerHTML=`<div class="notice"><b>${appMark("Post-freeze checks, original forecasts unchanged.")}</b> ${esc(d.classification)}${appMark(". This is a diagnostic version after additional research, not an improved original track record.")}</div><p>${appMark("Annual base forecast requires Q2–Q4 average revenue {revenue}m, {growth} above the guided first quarter. This is an explicit recovery/acceleration requirement, not management’s full-year guidance.",{revenue:n(b.requiredQ2ThroughQ4AverageRevenue,0),growth:pct(b.remainingQuarterAverageVsQ1)})}</p>${activeCase.snapshotId==='NVDA-FY2022'?`<p class="error">${appMark("Known risk omitted from the original narrative: sales to Russia had ceased by the filing; February earnings guidance predated the invasion. The original March case was not a comprehensive event-adjusted forecast. No unsupported geographic loss is invented here.")}</p>`:''}${activeCase.snapshotId==='NVDA-FY2021'?`<p class="error">${appMark("Standalone limitation: the original valuation omits the contingent Arm transaction. Closing cash, new shares, earnouts, incremental Arm value and net synergies require a separate state model. No closing probability is assigned, and the announced deal price is not intrinsic value.")}</p>`:''}${activeCase.snapshotId==='NVDA-FY2024'?`<p class="micro">${appMark("Concentration denominators matter: the China 14% reference is a share of Data Center revenue; the indirect-customer 19% reference is a share of total revenue.")}</p>`:''}<h3>${appMark("Historical rate anchors, assumed beta")}</h3><p><a href="${esc(rf.sourceURL)}" target="_blank" rel="noopener">${appMark("Prior-session 10-year Treasury")}</a>: ${n(rf.percentPerYear,2)}% (${esc(rf.observationDate)}). <a href="${esc(erp.sourceURL)}" target="_blank" rel="noopener">${appMark("Dated January ERP")}</a>: ${n(erp.percentPerYear,2)}${appMark("%. Historical Treasury observations are from the current official series, not certified as-released vintages.")}</p>${table(['Assumed initial beta','Initial discount rate','Terminal discount rate','Conditional value / share'],c.stresses.map(s=>[n(s.assumedInitialOperatingBeta,1),pct(s.initialUnleveredDiscountRate),pct(s.terminalUnleveredDiscountRate),n(s.perShare,2)]))}<p class="micro">${esc(d.method)} ${esc(d.limitations.join(' '))}${appMark(" These hypothetical all-equity operating rates omit debt tax shields and are not a reconstruction of historical levered WACC.")}</p>`}catch(e){appText($('#research-addenda-results'),e.message)}};

