$('#claim-scale').onclick=async()=>{try{if(!activeCase?.snapshotId?.startsWith('NVDA'))throw new Error('Load a dated NVIDIA research case first');const d=await(await fetch('./data/nvda-claim-scale-diagnostics.json')).json(),award=d.awards.cases.find(c=>c.snapshotId===activeCase.snapshotId);let html=`<div class="notice">${appMark("Post-freeze source checks. Original forecasts and scores remain unchanged.")}</div><h3>${appMark("Existing equity awards: evidence, not a completed net claim")}</h3><p><a href="${esc(award.sourceUrl)}" target="_blank" rel="noopener">${appMark("Original filing award note ↗")}</a>${appMark(": {units}m units outstanding at {date}, {percent} of cover-date shares. Period-end award counts and cover-date common shares are different dated observations.",{units:n(award.awardUnitsOutstandingMillions,0),date:award.sourceDate,percent:pct(award.grossUnitsAsPctOfCoverShares)})}</p><p class="micro">${esc(d.awards.method)} ${esc(d.awards.noDoubleCounting)} ${esc(d.awards.remainingGap)}</p>`;if(activeCase.snapshotId==='NVDA-FY2024'){const z=d.scale;html+=`<h3>${appMark("Does the implied terminal scale fit a market?")}</h3><p><a href="${esc(z.source.url)}" target="_blank" rel="noopener">${appMark("Issuer October 2023 presentation, page 33 ↗")}</a>${appMark(": $300bn Data Center Systems and $1tn broader long-term annual opportunity claims. This is promotional, untimed issuer evidence, not a validated customer-spending forecast. Do not confuse installed infrastructure stock with annual spending.")}</p>${table(['Original state','First terminal-year revenue ($bn)','Implied Data Center share of $300bn TAM'],z.cases.map(c=>[esc(c.state),n(c.firstTerminalYearRevenueUSDmillions/1000,1),pct(c.constantCurrentPlatformMixDiagnostic.shareOfManagement300bnDataCenterSystemsOpportunity)]))}<p class="error">${appMark("The original bull path implies 152.7% of the issuer’s stated Data Center Systems opportunity if the current platform mix is held constant. It requires market expansion, a different category/mix, or a revised revenue path. It is not established as feasible by this model.")}</p><p class="micro">${esc(z.interpretation)} ${esc(z.constraints.join(' '))}</p><h3>${appMark("Separate precision & capital checks")}</h3><p>${appMark("The exact platform-growth bridge is 68.5072%; the original 70% judgment adds $909.45m first-year revenue. A separate exact-bridge case gives $403.52 per share versus the preserved $406.98 original. ")}${esc(d.method2024.capitalMechanism)}</p><p class="micro">${esc(d.method2024.knownCommitments.treatment)} ${esc(d.method2024.shareCountCaveat)}</p>`;}$('#claim-scale-results').innerHTML=html}catch(e){appText($('#claim-scale-results'),e.message)}};
